    private static str totalQuantity()
    {
        SysDictTable    dictPurchLine    = new SysDictTable(tableNum(PurchLine));
        SysDictTable    dictMetPurchLine = new SysDictTable(tableNum(METPurchLine));
        PurchId         purchId          = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderHeaderV2Entity),
                                                                         dataEntityDataSourceStr(PurchPurchaseOrderHeaderV2Entity, PurchTable),
                                                                         fieldStr(PurchTable, PurchId));

        const str query = "SELECT SUM(%1.%2) FROM %1 WHERE %1.%3 = %4";
        
        str totalQty = strFmt(query, dictPurchLine.name(DbBackend::Sql),
                                dictPurchLine.fieldName(fieldNum(PurchLine, PurchQty), DbBackend::Sql),
                                dictPurchLine.fieldName(fieldNum(PurchLine, PurchId), DbBackend::Sql),
                                purchId);
        
        return totalQty;
    }

    /// <summary>
    /// Method to process composite entity logic
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">Type DefinitionGroupExecution</param>
    public static void metProcessDataForCompositeEntity(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        PurchPurchaseOrderHeaderV2Staging  metStaging;
        VendPurchOrderJour                 vendPurchOrderJour;
        PurchTable                         purchTable;
        METSalesTable                      metSalesTable;
        SalesTable                         salesTable;
        DMFEntity                          dmfEntity, dmfParentEntity;

        #OCCRetryCount

        try
        {
                    
            while select PurchaseOrderNumber from metStaging
                where metStaging.DefinitionGroup    == _dmfDefinitionGroupExecution.DefinitionGroup
                   && metStaging.ExecutionId           == _dmfDefinitionGroupExecution.ExecutionId
                   && metStaging.TransferStatus        == DMFTransferStatus::Completed
                notexists join RecId from vendPurchOrderJour
                    where vendPurchOrderJour.PurchId == metStaging.PurchaseOrderNumber
            {
                select firstonly PurchId, DataAreaId, InterCompanyOrder, InterCompanyCompanyId, InterCompanySalesId from purchTable
                            where purchTable.PurchId == metStaging.PurchaseOrderNumber;

                if(purchTable.DocumentState == VersioningDocumentState::Draft)
                {
                    METPurchPurchaseOrderHeaderV2Entity::poAutoApprovalService(purchTable.DataAreaId, purchTable.PurchId);
                }
                if(purchTable.InterCompanyOrder)
                {
                    changecompany(purchTable.InterCompanyCompanyId)
                    {
                        select firstonly forupdate metSalesTable
                                    join RecId from salesTable
                                       where salesTable.RecId == metSalesTable.SalesTable
                                          && salesTable.SalesId == purchTable.InterCompanySalesId;
                        if(metSalesTable.RecId)
                        {
                            ttsbegin;
                            metSalesTable.SalesDespatchDay = metStaging.METSalesDespatchDay;
                            metSalesTable.SalesDespatchTime = metStaging.METSalesDespatchTime;
                            metSalesTable.SalesCutOffDay = metStaging.METSalesCutOffDay;
                            metSalesTable.SalesCutOffTime = metStaging.METSalesCutOffTime;
                            metSalesTable.StagingLaneId = metStaging.METStagingLaneId;
                            metSalesTable.Door = metStaging.METDoor;
                            metSalesTable.doUpdate();

                            salesTable.selectForUpdate(true);
                            salesTable.METRoute = metStaging.METRoute;
                            salesTable.METRouteStopNum = metStaging.METRouteStopNum;
                            salesTable.doUpdate();
                            ttscommit;
                        }

                    }
                }
            }
        }
        catch (Exception::Deadlock)
        {
            // retry on deadlock
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            // try to resolve update conflict
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        catch(Exception::Error)
        {
            throw Error(strFmt("@MET:POApprovalError",metStaging.PurchaseOrderNumber));
        }
    }

    /// <summary>
    /// MPJ-33014 - PO DR Import fields
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(PurchPurchaseOrderHeaderV2Entity, METPurchTable):
                METPurchTable metPurchTable = _dataSourceCtx.getBuffer();

                if(!metPurchTable.POIMPDestinationPort)
                {
                    metPurchTable.POIMPDestinationPort = InventSite::find(PurchTable::find(metPurchTable.purchId).InventSiteId).METPODestinationPortDefault;
                }
                break;
        }
        return next updateEntityDataSource(_entityCtx, _dataSourceCtx);;
    }
